%[text] # Two-node callback substructure under earthquake excitation
%[text] Compare the native OpenSees `ViscousDamper` with the same constitutive
%[text] law evaluated by a MATLAB callback. Four interface degrees of freedom
%[text] connect nodes 1 and 4; the callback projects their relative motion onto
%[text] the damper axis and returns balanced nodal forces. Units are mm, kN, and s.
clear;
clc;
close all;
exampleFolder = "";
%%
%[text] ## 1. OpenSeesMatlab interface
opsMAT = OpenSeesMatlab();
ops = opsMAT.opensees;
%%
%[text] ## 2. Output settings
outputFolder = fullfile(exampleFolder, "figures");

if ~exist(outputFolder, "dir")
    mkdir(outputFolder);
end

% resultMatFile = fullfile(exampleFolder, ...
%     "ShearFrameVD_TwoNodeSubstructure_Verification.mat");
% metricCsvFile = fullfile(exampleFolder, ...
%     "ShearFrameVD_TwoNodeSubstructure_Metrics.csv");
% timingCsvFile = fullfile(exampleFolder, ...
%     "ShearFrameVD_TwoNodeSubstructure_Timing.csv");
%%
%[text] ## 3. Structural model parameters
model.L = 5000.0;                         % Bay width, mm
model.h = 3000.0;                         % Story height, mm

model.W = 1000.0;                         % Seismic weight, kN
model.g = 9810.0;                         % Gravitational acceleration, mm/s^2
model.m = model.W / model.g;              % Roof mass, kN-s^2/mm

% Nonlinear steel-column frame model.
% The original elastic columns are replaced by Steel4 fiber-section
% forceBeamColumn elements. The roof beam remains elastic.
model.E = 200.0;                          % Steel elastic modulus, kN/mm^2

% Column Steel4 material with a finite ultimate-strength surface
model.column.matTag = 101;
model.column.secTag = 101;
model.column.beamIntegrationTag = 101;

model.column.Fy = 0.345;                  % kN/mm^2 = 345 MPa
model.column.E0 = model.E;                % kN/mm^2
model.column.b = 0.01;
model.column.R0 = 18.0;
model.column.cR1 = 0.925;
model.column.cR2 = 0.15;
model.column.Fu = 1.20 * model.column.Fy;
model.column.Ru = 20.0;

% Column H-section dimensions, mm
% This is the previously used nonlinear frame-column section.
model.column.d  = 300.0;
model.column.tw = 8.0;
model.column.bf = 220.0;
model.column.tf = 14.0;

% Fiber discretization for explicit Fiber section
model.column.nfdw = 16;
model.column.nftw = 2;
model.column.nfbf = 12;
model.column.nftf = 2;

model.column.numIntPts = 5;

% Elastic roof beam properties, mm
model.beam.E = model.E;
model.beam.d  = 500.0;
model.beam.tw = 12.0;
model.beam.bf = 300.0;
model.beam.tf = 20.0;
model.beam.stiffnessFactor = 10.0;

model.beam.A = ...
    2.0 * model.beam.bf * model.beam.tf + ...
    model.beam.tw * (model.beam.d - 2.0 * model.beam.tf);

model.beam.I = ...
    (model.beam.tw * (model.beam.d - 2.0 * model.beam.tf)^3) / 12.0 + ...
    2.0 * ( ...
        (model.beam.bf * model.beam.tf^3) / 12.0 + ...
        model.beam.bf * model.beam.tf * ((model.beam.d - model.beam.tf) / 2.0)^2 );

model.beam.Aeff = model.beam.stiffnessFactor * model.beam.A;
model.beam.Ieff = model.beam.stiffnessFactor * model.beam.I;

model.damperLength = hypot(model.L, model.h);
model.damperDirection = ...
    [model.L; model.h] / model.damperLength;

fprintf("Column section           = H%.0fx%.0fx%.0fx%.0f mm\n", ... %[output:group:5ecf0dd6] %[output:9f04a08e]
    model.column.d, model.column.bf, model.column.tw, model.column.tf); %[output:group:5ecf0dd6] %[output:9f04a08e]
fprintf("Beam stiffness factor    = %.3f\n", model.beam.stiffnessFactor); %[output:7d8b883e]
fprintf("Damper direction          = [%.6f, %.6f]\n", ... %[output:group:49cd3db1] %[output:0797d978]
    model.damperDirection(1), model.damperDirection(2)); %[output:group:49cd3db1] %[output:0797d978]
%%
%[text] ## 4. Nonlinear viscous damper parameters
%[text] The translated constitutive equation is:
%[text]   dF/dt = K  *\[v - sign(F)*(|F|/C)^(1/Alpha)\]
%[text] This simplified teaching example uses the same default method as the
%[text] supplied C++ implementation:
%[text]   NM = 1, Dormand-Prince 5(4).
damper.K = 25.0;                          % Series spring stiffness, kN/mm
damper.C = 20.7452;                       % Dashpot coefficient
damper.Alpha = 0.35;                      % Velocity exponent

damper.LGap = 0.0;                        % Gap length, mm
damper.NM = 1.0;                          % Dormand-Prince 5(4)
damper.RelTol = 1.0e-6;
damper.AbsTol = 1.0e-10;
damper.MaxHalf = 15.0;
%%
%[text] ## 5. Earthquake and transient-analysis parameters
analysis.dtGroundMotion = 0.01;
analysis.groundMotionScale = 0.50 * model.g;

analysis.dt = 0.001;
analysis.numberOfSteps = 10 * 4096;

analysis.dampingRatio = 0.02;
analysis.groundMotionFile = locateGroundMotionFile( ...
    ["TakY.th", "TAKY.th", "taky.th"], exampleFolder);

fprintf("Ground-motion file: %s\n", analysis.groundMotionFile); %[output:52ece0f0]
%%
%[text] ## 6. Display the earthquake input
groundMotionData = readmatrix( ...
    analysis.groundMotionFile, ...
    "FileType", "text");

groundMotionData = groundMotionData( ...
    any(isfinite(groundMotionData), 2), ...
    any(isfinite(groundMotionData), 1));

if isempty(groundMotionData)
    error("No valid numeric data were found in the earthquake file.");
end

groundMotionValues = groundMotionData(:, end);
groundMotionValues = groundMotionValues(isfinite(groundMotionValues));

groundMotionTime = ...
    (0:numel(groundMotionValues)-1)' * analysis.dtGroundMotion;

scaledGroundAcceleration = ...
    groundMotionValues * analysis.groundMotionScale / model.g;

figure( ... %[output:946b27dc]
    "Color", "w", ... %[output:946b27dc]
    "Units", "centimeters", ... %[output:946b27dc]
    "Position", [2, 2, 17.5, 7.0]); %[output:946b27dc]

plot(groundMotionTime, scaledGroundAcceleration, "k-", "LineWidth", 1.0); %[output:946b27dc]

xlabel("Time (s)"); %[output:946b27dc]
ylabel("Ground acceleration (g)"); %[output:946b27dc]
% title("Scaled earthquake input");

applyPublicationAxes(gca); %[output:946b27dc]
drawnow;
%%
%[text] ## 7. Run the complete OpenSees model
%[text] Timing includes:
%[text]   setupTime    : model generation and analysis configuration
%[text]   analysisTime : nonlinear transient analysis loop
%[text]   totalTime    : setupTime + analysisTime
fprintf("\nRunning complete OpenSees model...\n"); %[output:77245196]
[complete, completeTiming] = runDynamicCase( ... %[output:group:741f2930] %[output:977ab0ba]
    ops, ... %[output:977ab0ba]
    "complete", ... %[output:977ab0ba]
    model, ... %[output:977ab0ba]
    damper, ... %[output:977ab0ba]
    analysis); %[output:group:741f2930] %[output:977ab0ba]
fprintf("Complete-model analysis finished.\n"); %[output:45609f13]
%%
%[text] ## 8. Run the two-node MATLAB substructure model
fprintf("\nRunning two-node MATLAB substructure model...\n"); %[output:9e3cf4bb]
[substructure, substructureTiming] = runDynamicCase( ... %[output:group:279f62dc] %[output:623b044d]
    ops, ... %[output:623b044d]
    "substructure", ... %[output:623b044d]
    model, ... %[output:623b044d]
    damper, ... %[output:623b044d]
    analysis); %[output:group:279f62dc] %[output:623b044d]
fprintf("MATLAB-substructure analysis finished.\n"); %[output:476d2308]
%%
%[text] ## 9. Align the response histories
numberOfCommonPoints = min( ...
    numel(complete.time), ...
    numel(substructure.time));

complete = truncateResponse(complete, numberOfCommonPoints);
substructure = truncateResponse(substructure, numberOfCommonPoints);
%%
%[text] ## 10. Calculate response differences and verification metrics
responseError.displacement = ...
    substructure.roofDisp - complete.roofDisp;

responseError.velocity = ...
    substructure.roofVel - complete.roofVel;

responseError.acceleration = ...
    substructure.roofAccel - complete.roofAccel;

responseError.damperDeformation = ...
    substructure.damperDeformation - complete.damperDeformation;

responseError.damperVelocity = ...
    substructure.damperVelocity - complete.damperVelocity;

responseError.damperForce = ...
    substructure.damperForce - complete.damperForce;

metrics = calculateVerificationMetrics( ...
    complete, ...
    substructure, ...
    responseError, ...
    model.g);
%%
%[text] ## 11. Compare computational time
timing.CompleteSetup_s = completeTiming.setupTime;
timing.CompleteAnalysis_s = completeTiming.analysisTime;
timing.CompleteTotal_s = completeTiming.totalTime;

timing.SubstructureSetup_s = substructureTiming.setupTime;
timing.SubstructureAnalysis_s = substructureTiming.analysisTime;
timing.SubstructureTotal_s = substructureTiming.totalTime;

timing.AnalysisTimeRatio = ...
    substructureTiming.analysisTime / max(completeTiming.analysisTime, eps);

timing.TotalTimeRatio = ...
    substructureTiming.totalTime / max(completeTiming.totalTime, eps);

timing.AnalysisOverhead_percent = ...
    100.0 * (substructureTiming.analysisTime - completeTiming.analysisTime) / ...
    max(completeTiming.analysisTime, eps);

timing.TotalOverhead_percent = ...
    100.0 * (substructureTiming.totalTime - completeTiming.totalTime) / ...
    max(completeTiming.totalTime, eps);
%%
%[text] ## 12. Display numerical verification summary
fprintf("\n");
fprintf("Response verification summary\n"); %[output:5851b618]
fprintf("====================================================================\n"); %[output:6245be12]
fprintf("Peak roof displacement, complete       = %14.6e mm\n", ... %[output:group:23a1ebea] %[output:03f3aa2d]
    metrics.PeakDispComplete_mm); %[output:group:23a1ebea] %[output:03f3aa2d]
fprintf("Peak roof displacement, substructure   = %14.6e mm\n", ... %[output:group:93cd225f] %[output:8b6d43c4]
    metrics.PeakDispSubstructure_mm); %[output:group:93cd225f] %[output:8b6d43c4]
fprintf("Roof displacement NRMSE                = %14.6e %%n", ... %[output:group:25015929] %[output:36ec507d]
    metrics.DispNRMSE_percent); %[output:group:25015929] %[output:36ec507d]
fprintf("Roof displacement correlation          = %14.8f\n", ... %[output:group:6b45dbd8] %[output:3357cd51]
    metrics.DispCorrelation); %[output:group:6b45dbd8] %[output:3357cd51]
fprintf("--------------------------------------------------------------------\n"); %[output:6f39b1ee]
fprintf("Peak roof acceleration, complete       = %14.6e g\n", ... %[output:group:2e811cf1] %[output:275961ce]
    metrics.PeakAccelComplete_g); %[output:group:2e811cf1] %[output:275961ce]
fprintf("Peak roof acceleration, substructure   = %14.6e g\n", ... %[output:group:5635cad4] %[output:444a363a]
    metrics.PeakAccelSubstructure_g); %[output:group:5635cad4] %[output:444a363a]
fprintf("Roof acceleration NRMSE                = %14.6e %%n", ... %[output:group:88051a4a] %[output:2cf9cb92]
    metrics.AccelNRMSE_percent); %[output:group:88051a4a] %[output:2cf9cb92]
fprintf("--------------------------------------------------------------------\n"); %[output:8cf689ba]
fprintf("Peak damper force, complete             = %14.6e kN\n", ... %[output:group:903fcc56] %[output:05675f30]
    metrics.PeakForceComplete_kN); %[output:group:903fcc56] %[output:05675f30]
fprintf("Peak damper force, substructure         = %14.6e kN\n", ... %[output:group:5c364d4e] %[output:90bd5c84]
    metrics.PeakForceSubstructure_kN); %[output:group:5c364d4e] %[output:90bd5c84]
fprintf("Damper-force NRMSE                     = %14.6e %%n", ... %[output:group:11bf9e32] %[output:08f9684e]
    metrics.ForceNRMSE_percent); %[output:group:11bf9e32] %[output:08f9684e]
fprintf("Damper-force correlation               = %14.8f\n", ... %[output:group:69f43f96] %[output:244b6df4]
    metrics.ForceCorrelation); %[output:group:69f43f96] %[output:244b6df4]
fprintf("====================================================================\n"); %[output:72ec3353]


fprintf("\n");
fprintf("Computational-time comparison\n"); %[output:9b100e6b]
fprintf("====================================================================\n"); %[output:5813ea27]
fprintf("Complete-model setup time              = %12.4f s\n", ... %[output:group:794cbe19] %[output:2e61d74c]
    timing.CompleteSetup_s); %[output:group:794cbe19] %[output:2e61d74c]
fprintf("Complete-model analysis time           = %12.4f s\n", ... %[output:group:63452e01] %[output:73044239]
    timing.CompleteAnalysis_s); %[output:group:63452e01] %[output:73044239]
fprintf("Complete-model total time              = %12.4f s\n", ... %[output:group:195ba8c0] %[output:8ac454cc]
    timing.CompleteTotal_s); %[output:group:195ba8c0] %[output:8ac454cc]
fprintf("--------------------------------------------------------------------\n"); %[output:582f17ce]
fprintf("Substructure setup time                = %12.4f s\n", ... %[output:group:0a27d89f] %[output:9c119694]
    timing.SubstructureSetup_s); %[output:group:0a27d89f] %[output:9c119694]
fprintf("Substructure analysis time             = %12.4f s\n", ... %[output:group:2b52de37] %[output:75ba2169]
    timing.SubstructureAnalysis_s); %[output:group:2b52de37] %[output:75ba2169]
fprintf("Substructure total time                = %12.4f s\n", ... %[output:group:4ef9086a] %[output:60ec4a36]
    timing.SubstructureTotal_s); %[output:group:4ef9086a] %[output:60ec4a36]
fprintf("--------------------------------------------------------------------\n"); %[output:3d534fce]
fprintf("Analysis-time ratio, sub/complete      = %12.4f\n", ... %[output:group:1159e2e1] %[output:416f6ef5]
    timing.AnalysisTimeRatio); %[output:group:1159e2e1] %[output:416f6ef5]
fprintf("Total-time ratio, sub/complete         = %12.4f\n", ... %[output:group:23e560c2] %[output:72f5c12f]
    timing.TotalTimeRatio); %[output:group:23e560c2] %[output:72f5c12f]
fprintf("Analysis-time overhead                 = %12.2f %%n", ... %[output:group:977f9f6e] %[output:5a4c7dce]
    timing.AnalysisOverhead_percent); %[output:group:977f9f6e] %[output:5a4c7dce]
fprintf("Total-time overhead                    = %12.2f %%n", ... %[output:group:473253e9] %[output:01a2ba32]
    timing.TotalOverhead_percent); %[output:group:473253e9] %[output:01a2ba32]
fprintf("--------------------------------------------------------------------\n"); %[output:77467162]
fprintf("MATLAB callback calls                  = %12.0f\n", ... %[output:group:88a38328] %[output:28b5029c]
    substructureTiming.callbackCallCount); %[output:group:88a38328] %[output:28b5029c]
fprintf("MATLAB trial callback calls            = %12.0f\n", ... %[output:group:8f12586c] %[output:5ba8dd14]
    substructureTiming.trialCallbackCallCount); %[output:group:8f12586c] %[output:5ba8dd14]
fprintf("Committed revisions                    = %12.0f\n", ... %[output:group:00967e35] %[output:08570724]
    substructureTiming.committedRevision); %[output:group:00967e35] %[output:08570724]
fprintf("Cumulative MATLAB callback time        = %12.4f s\n", ... %[output:group:03ed4e8f] %[output:29ef5e7c]
    substructureTiming.callbackTime); %[output:group:03ed4e8f] %[output:29ef5e7c]
fprintf("Mean MATLAB callback time              = %12.6e s\n", ... %[output:group:52864bfe] %[output:1e431b4a]
    substructureTiming.meanCallbackTime); %[output:group:52864bfe] %[output:1e431b4a]
fprintf("Maximum MATLAB callback time           = %12.6e s\n", ... %[output:group:3570920f] %[output:200f5420]
    substructureTiming.maxCallbackTime); %[output:group:3570920f] %[output:200f5420]
fprintf("Callback fraction of analysis time     = %12.2f %%n", ... %[output:group:99d5904f] %[output:4ab1db7e]
    substructureTiming.callbackFraction_percent); %[output:group:99d5904f] %[output:4ab1db7e]
fprintf("====================================================================\n\n"); %[output:365b8b03]
%%
%[text] ## 13. Roof-response comparison

figureHandle = figure( ... %[output:3bd12531]
    "Color", "w", ... %[output:3bd12531]
    "Units", "centimeters", ... %[output:3bd12531]
    "Position", [2, 2, 18.0, 14.0]); %[output:3bd12531]

layout = tiledlayout( ... %[output:3bd12531]
    3, 1, ... %[output:3bd12531]
    "TileSpacing", "compact", ... %[output:3bd12531]
    "Padding", "compact"); %[output:3bd12531]

% -------------------------------------------------------------------------
% Roof displacement
% -------------------------------------------------------------------------
nexttile; %[output:3bd12531]

plotComparison( ... %[output:3bd12531]
    complete.time, complete.roofDisp, ... %[output:3bd12531]
    substructure.time, substructure.roofDisp); %[output:3bd12531]

ylabel("Roof displacement (mm)"); %[output:3bd12531]

legend( ... %[output:3bd12531]
    {"Complete model", "MATLAB substructure"}, ... %[output:3bd12531]
    "Location", "northeast", ... %[output:3bd12531]
    "Box", "on", ... %[output:3bd12531]
    "Color", "white", ... %[output:3bd12531]
    "EdgeColor", [0.35, 0.35, 0.35], ... %[output:3bd12531]
    "NumColumns", 2); %[output:3bd12531]

maxAbsDiffDisp = max(abs(substructure.roofDisp - complete.roofDisp));

text( ... %[output:3bd12531]
    0.98, 0.75, ... %[output:3bd12531]
    sprintf("Max abs. diff. = %.3e mm", maxAbsDiffDisp), ... %[output:3bd12531]
    "Units", "normalized", ... %[output:3bd12531]
    "HorizontalAlignment", "right", ... %[output:3bd12531]
    "VerticalAlignment", "top", ... %[output:3bd12531]
    "Interpreter", "none", ... %[output:3bd12531]
    "FontSize", 10, ... %[output:3bd12531]
    "BackgroundColor", "w", ... %[output:3bd12531]
    "EdgeColor", "none", ... %[output:3bd12531]
    "Margin", 2); %[output:3bd12531]

applyPublicationAxes(gca); %[output:3bd12531]

% -------------------------------------------------------------------------
% Roof velocity
% -------------------------------------------------------------------------
nexttile; %[output:3bd12531]

plotComparison( ... %[output:3bd12531]
    complete.time, complete.roofVel, ... %[output:3bd12531]
    substructure.time, substructure.roofVel); %[output:3bd12531]

ylabel("Roof velocity (mm/s)"); %[output:3bd12531]

maxAbsDiffVel = max(abs(substructure.roofVel - complete.roofVel));

text( ... %[output:3bd12531]
    0.98, 0.92, ... %[output:3bd12531]
    sprintf("Max abs. diff. = %.3e mm/s", maxAbsDiffVel), ... %[output:3bd12531]
    "Units", "normalized", ... %[output:3bd12531]
    "HorizontalAlignment", "right", ... %[output:3bd12531]
    "VerticalAlignment", "top", ... %[output:3bd12531]
    "Interpreter", "none", ... %[output:3bd12531]
    "FontSize", 10, ... %[output:3bd12531]
    "BackgroundColor", "w", ... %[output:3bd12531]
    "EdgeColor", "none", ... %[output:3bd12531]
    "Margin", 2); %[output:3bd12531]

applyPublicationAxes(gca); %[output:3bd12531]

% -------------------------------------------------------------------------
% Roof acceleration
% -------------------------------------------------------------------------
nexttile; %[output:3bd12531]

completeAccel_g = complete.roofAccel / model.g;
substructureAccel_g = substructure.roofAccel / model.g;

plotComparison( ... %[output:3bd12531]
    complete.time, completeAccel_g, ... %[output:3bd12531]
    substructure.time, substructureAccel_g); %[output:3bd12531]

xlabel("Time (s)"); %[output:3bd12531]
ylabel("Roof acceleration (g)"); %[output:3bd12531]

maxAbsDiffAccel = max(abs(substructureAccel_g - completeAccel_g));

text( ... %[output:3bd12531]
    0.98, 0.92, ... %[output:3bd12531]
    sprintf("Max abs. diff. = %.3e g", maxAbsDiffAccel), ... %[output:3bd12531]
    "Units", "normalized", ... %[output:3bd12531]
    "HorizontalAlignment", "right", ... %[output:3bd12531]
    "VerticalAlignment", "top", ... %[output:3bd12531]
    "Interpreter", "none", ... %[output:3bd12531]
    "FontSize", 10, ... %[output:3bd12531]
    "BackgroundColor", "w", ... %[output:3bd12531]
    "EdgeColor", "none", ... %[output:3bd12531]
    "Margin", 2); %[output:3bd12531]

applyPublicationAxes(gca); %[output:3bd12531]

drawnow;

exportPublicationFigure( ... %[output:group:0a44d7e2] %[output:3bd12531] %[output:329f77a6]
    figureHandle, ... %[output:3bd12531] %[output:329f77a6]
    outputFolder, ... %[output:3bd12531] %[output:329f77a6]
    "Substructure-RoofResponseComparison"); %[output:group:0a44d7e2] %[output:3bd12531] %[output:329f77a6]

roofFigureData = table( ...
    complete.time, complete.roofDisp, complete.roofVel, completeAccel_g, ...
    substructure.time, substructure.roofDisp, substructure.roofVel, ...
    substructureAccel_g, ...
    'VariableNames', {'CompleteTime_s','CompleteDisplacement_mm', ...
    'CompleteVelocity_mm_s','CompleteAcceleration_g', ...
    'SubstructureTime_s','SubstructureDisplacement_mm', ...
    'SubstructureVelocity_mm_s','SubstructureAcceleration_g'});
writetable(roofFigureData, ...
    fullfile(outputFolder, "Substructure-RoofResponseComparison.csv"));
%%
%[text] ## 14. Damper response comparison
figureHandle = figure( ... %[output:778d4456]
    "Color", "w", ... %[output:778d4456]
    "Units", "centimeters", ... %[output:778d4456]
    "Position", [2, 2, 18.0, 8.5]); %[output:778d4456]

tiledlayout( ... %[output:778d4456]
    1, 2, ... %[output:778d4456]
    "TileSpacing", "compact", ... %[output:778d4456]
    "Padding", "compact"); %[output:778d4456]

% -------------------------------------------------------------------------
% Energy difference based on force-deformation loop
% -------------------------------------------------------------------------
energyComplete = trapz(complete.damperDeformation, complete.damperForce);
energySubstructure = trapz(substructure.damperDeformation, substructure.damperForce);

energyDiff = energySubstructure - energyComplete;
energyDiffAbs = abs(energyDiff);

energyDiffPercent = ...
    100.0 * energyDiffAbs / max(abs(energyComplete), eps);

energyText = sprintf( ...
    "Energy diff. = %.3e kN-mm", ...
    energyDiffAbs);

% -------------------------------------------------------------------------
% Damper force-deformation
% -------------------------------------------------------------------------
nexttile; %[output:778d4456]

plotComparison( ... %[output:778d4456]
    complete.damperDeformation, complete.damperForce, ... %[output:778d4456]
    substructure.damperDeformation, substructure.damperForce); %[output:778d4456]

xlabel("Axial deformation (mm)"); %[output:778d4456]
ylabel("Damper force (kN)"); %[output:778d4456]

text( ... %[output:778d4456]
    0.98, 0.1, ... %[output:778d4456]
    energyText, ... %[output:778d4456]
    "Units", "normalized", ... %[output:778d4456]
    "HorizontalAlignment", "right", ... %[output:778d4456]
    "VerticalAlignment", "top", ... %[output:778d4456]
    "Interpreter", "none", ... %[output:778d4456]
    "FontSize", 10, ... %[output:778d4456]
