%[text] ## Local functions
function [response, timing] = runDynamicCase( ...
    ops, caseType, model, damper, analysis)
%RUNDYNAMICCASE Build and analyze one complete or substructure model.
%
% caseType:
%
%   "complete"     : native OpenSees ViscousDamper
%   "substructure" : MATLAB callback through callbackSubstructure

    caseType = lower(string(caseType));

    totalTimer = tic;
    setupTimer = tic;

    ops.wipe();

    if caseType == "substructure"
        ops.clearCallbackSubstructures();
    end

    buildFrameModel(ops, model);

    damperElementTag = 4;

    if caseType == "complete"

        materialTag = 1;

        ops.uniaxialMaterial( ...
            "ViscousDamper", ...
            materialTag, ...
            damper.K, ...
            damper.C, ...
            damper.Alpha, ...
            damper.LGap, ...
            damper.NM, ...
            damper.RelTol, ...
            damper.AbsTol, ...
            damper.MaxHalf);

        ops.element( ...
            "twoNodeLink", ...
            damperElementTag, ...
            1, 4, ...
            "-mat", materialTag, ...
            "-dir", 1);

    elseif caseType == "substructure"

        initialState = createInitialDamperState( ...
            damper, ...
            model.damperDirection);

        interfacePairs = [
            1, 1
            1, 2
            4, 1
            4, 2
        ];

        ops.callbackSubstructure( ...
            damperElementTag, ...
            @viscousDamperCppCallback, ...
            initialState, ...
            zeros(4, 4), ...
            interfacePairs, ...
            "tangentMode", "matlab");

    else
        error("Unknown analysis case: %s", caseType);
    end

    eigenvalue = ops.eigen(1);
    omega1 = sqrt(eigenvalue(1));
    period1 = 2*pi/omega1;

    ops.rayleigh( ...
        2.0*analysis.dampingRatio*omega1, ...
        0.0, 0.0, 0.0);

    ops.timeSeries( ...
        "Path", ...
        1, ...
        "-dt", analysis.dtGroundMotion, ...
        "-filePath", analysis.groundMotionFile, ...
        "-factor", analysis.groundMotionScale);

    ops.pattern( ...
        "UniformExcitation", ...
        1, ...
        1, ...
        "-accel", 1);

    configureTransientAnalysis(ops);

    timing.setupTime = toc(setupTimer);

    fprintf("%s first-mode period = %.8f s\n", caseType, period1);

    numberOfPoints = analysis.numberOfSteps + 1;

    response.time = zeros(numberOfPoints, 1);
    response.roofDisp = zeros(numberOfPoints, 1);
    response.roofVel = zeros(numberOfPoints, 1);
    response.roofAccel = zeros(numberOfPoints, 1);

    response.damperDeformation = zeros(numberOfPoints, 1);
    response.damperVelocity = zeros(numberOfPoints, 1);
    response.damperForce = zeros(numberOfPoints, 1);

    response.period = period1;

    forceAvailable = true;
    lastPoint = numberOfPoints;

    analysisTimer = tic;

    for step = 1:analysis.numberOfSteps

        ok = ops.analyze(1, analysis.dt);

        if ok ~= 0
            ops.test("EnergyIncr", 1.0e-9, 200, 0);
            ops.algorithm("Newton");

            ok = ops.analyze(1, analysis.dt);

            ops.test("EnergyIncr", 1.0e-10, 100, 0);
            ops.algorithm("KrylovNewton");
        end

        if ok ~= 0
            lastPoint = step;

            warning( ...
                "%s analysis stopped at step %d, time %.6f s.", ...
                caseType, ...
                step, ...
                ops.getTime());

            break;
        end

        index = step + 1;

        node1Disp = [
            ops.nodeDisp(1, 1)
            ops.nodeDisp(1, 2)
        ];

        node4Disp = [
            ops.nodeDisp(4, 1)
            ops.nodeDisp(4, 2)
        ];

        node1Vel = [
            ops.nodeVel(1, 1)
            ops.nodeVel(1, 2)
        ];

        node4Vel = [
            ops.nodeVel(4, 1)
            ops.nodeVel(4, 2)
        ];

        relativeDisp = node4Disp - node1Disp;
        relativeVel = node4Vel - node1Vel;

        response.time(index) = ops.getTime();
        response.roofDisp(index) = node4Disp(1);
        response.roofVel(index) = node4Vel(1);
        response.roofAccel(index) = ops.nodeAccel(4, 1);

        response.damperDeformation(index) = ...
            model.damperDirection.' * relativeDisp;

        response.damperVelocity(index) = ...
            model.damperDirection.' * relativeVel;

        if forceAvailable
            [forceAvailable, currentForce] = readDamperForce( ...
                ops, ...
                damperElementTag, ...
                caseType, ...
                model.damperDirection);

            if forceAvailable
                response.damperForce(index) = currentForce;
            end
        end

        if mod(step, 5000) == 0
            fprintf( ...
                "%s: step %6d of %6d, time = %8.3f s\n", ...
                caseType, ...
                step, ...
                analysis.numberOfSteps, ...
                ops.getTime());
        end
    end

    timing.analysisTime = toc(analysisTimer);
    timing.totalTime = toc(totalTimer);

    % The extended callbackSubstructure response API exposes callback statistics
    % without executing MATLAB again. These values quantify the communication
    % and callback overhead separately from the total OpenSees analysis time.
    if caseType == "substructure"
        timing.callbackCallCount = ...
            scalarElementResponse(ops, damperElementTag, "callCount");

        timing.trialCallbackCallCount = ...
            scalarElementResponse(ops, damperElementTag, "trialCallCount");

        timing.committedRevision = ...
            scalarElementResponse(ops, damperElementTag, "committedRevision");

        timing.callbackTime = ...
            scalarElementResponse(ops, damperElementTag, "callbackTime");

        timing.lastCallbackTime = ...
            scalarElementResponse(ops, damperElementTag, "lastCallbackTime");

        timing.maxCallbackTime = ...
            scalarElementResponse(ops, damperElementTag, "maxCallbackTime");

        timing.meanCallbackTime = ...
            scalarElementResponse(ops, damperElementTag, "meanCallbackTime");

        timing.callbackFraction_percent = ...
            100.0 * timing.callbackTime / max(timing.analysisTime, eps);
    else
        timing.callbackCallCount = 0.0;
        timing.trialCallbackCallCount = 0.0;
        timing.committedRevision = 0.0;
        timing.callbackTime = 0.0;
        timing.lastCallbackTime = 0.0;
        timing.maxCallbackTime = 0.0;
        timing.meanCallbackTime = 0.0;
        timing.callbackFraction_percent = 0.0;
    end

    response = truncateResponse(response, lastPoint);

    if ~forceAvailable || max(abs(response.damperForce)) <= eps
        warning( ...
            "%s damper force is reconstructed from converged histories.", ...
            caseType);

        response.damperForce = replayViscousDamperCpp( ...
            response.damperDeformation, ...
            response.damperVelocity, ...
            response.time, ...
            damper);
    end

    if caseType == "substructure"
        try
            ops.unregisterCallbackSubstructure(damperElementTag);
        catch
        end
    end
end


function value = scalarElementResponse(ops, elementTag, responseName)
%SCALARELEMENTRESPONSE Read a scalar diagnostic from callbackSubstructure.
%
% Returning NaN rather than stopping the analysis makes the example compatible
% with wrappers that have not yet exposed a particular response alias.

    try
        rawValue = ops.eleResponse(elementTag, responseName);
        rawValue = rawValue(:);

        if isempty(rawValue)
            value = NaN;
        else
            value = rawValue(1);
        end
    catch
        value = NaN;
    end
end


function buildFrameModel(ops, model)
%BUILDFRAMEMODEL Generate the common nonlinear steel-column frame.
%
% Columns:
%   Steel4 + Fiber section + forceBeamColumn
%
% Roof beam:
%   elasticBeamColumn
%
% The same frame model is used by both the complete OpenSees damper case and
% the MATLAB-substructure damper case. Only the damper representation changes.

    ops.model("BasicBuilder", "-ndm", 2, "-ndf", 3);

    ops.node(1, 0.0,     0.0);
    ops.node(2, model.L, 0.0);
    ops.node(3, 0.0,     model.h);
    ops.node(4, model.L, model.h);

    ops.fix(1, 1, 1, 1);
    ops.fix(2, 1, 1, 1);

    % Shear-frame roof constraint
    ops.equalDOF(3, 4, 2, 3);

    ops.mass(3, 0.5*model.m, 0.0, 0.0);
    ops.mass(4, 0.5*model.m, 0.0, 0.0);

    transformationTag = 1;
    ops.geomTransf("Linear", transformationTag);

    % ------------------------------------------------------------------
    % Nonlinear Steel4 material for the columns. The ultimate-strength
    % surface prevents indefinite stress growth under continued hardening.
    % ------------------------------------------------------------------

    col = model.column;

    ops.uniaxialMaterial( ...
        "Steel4", ...
        col.matTag, ...
        col.Fy, ...
        col.E0, ...
        "-kin", ...
        col.b, ...
        col.R0, ...
        col.cR1, ...
        col.cR2, ...
        "-ult", ...
        col.Fu, ...
        col.Ru);

    % ------------------------------------------------------------------
    % Explicit fiber section for the column H-section
    % ------------------------------------------------------------------

    yTop   =  0.5 * col.d;
    yBot   = -0.5 * col.d;
    zLeft  = -0.5 * col.bf;
    zRight =  0.5 * col.bf;
    zWebL  = -0.5 * col.tw;
    zWebR  =  0.5 * col.tw;

    yTopFlangeBot =  0.5 * col.d - col.tf;
    yBotFlangeTop = -0.5 * col.d + col.tf;

    ops.section("Fiber", col.secTag);

    % Top flange
    ops.patch( ...
        "rect", ...
        col.matTag, ...
        col.nftf, ...
        col.nfbf, ...
        yTopFlangeBot, zLeft, ...
        yTop,          zRight);

    % Web
    ops.patch( ...
        "rect", ...
        col.matTag, ...
        col.nfdw, ...
        col.nftw, ...
        yBotFlangeTop, zWebL, ...
        yTopFlangeBot, zWebR);

    % Bottom flange
    ops.patch( ...
        "rect", ...
        col.matTag, ...
        col.nftf, ...
        col.nfbf, ...
        yBot,          zLeft, ...
        yBotFlangeTop, zRight);

    ops.beamIntegration( ...
        "Lobatto", ...
        col.beamIntegrationTag, ...
        col.secTag, ...
        col.numIntPts);

    % ------------------------------------------------------------------
    % Elements
    % ------------------------------------------------------------------

    % Nonlinear steel columns
    ops.element( ...
        "forceBeamColumn", ...
        1, 1, 3, ...
        transformationTag, ...
        col.beamIntegrationTag);

    ops.element( ...
        "forceBeamColumn", ...
        2, 2, 4, ...
        transformationTag, ...
        col.beamIntegrationTag);

    % Elastic roof beam
    ops.element( ...
        "elasticBeamColumn", ...
        3, 3, 4, ...
        model.beam.Aeff, ...
        model.beam.E, ...
        model.beam.Ieff, ...
        transformationTag);
end


function configureTransientAnalysis(ops)
%CONFIGURETRANSIENTANALYSIS Define the common nonlinear solver settings.

    ops.wipeAnalysis();

    ops.constraints("Transformation");
    ops.numberer("RCM");
    ops.system("UmfPack");

    ops.test("EnergyIncr", 1.0e-10, 100, 0);
    ops.algorithm("KrylovNewton");

    ops.integrator("Newmark", 0.5, 0.25);
    ops.analysis("Transient");
end


function state = createInitialDamperState(damper, direction)
%CREATEINITIALDAMPERSTATE Initialize the MATLAB constitutive state.

    state.K = damper.K;
    state.C = damper.C;
    state.Alpha = damper.Alpha;

    state.LGap = damper.LGap;
    state.NM = damper.NM;
    state.RelTol = damper.RelTol;
    state.AbsTol = damper.AbsTol;
    state.MaxHalf = damper.MaxHalf;

    state.direction = direction(:);

    state.Cstrain = 0.0;
    state.Cstress = 0.0;
    state.CVel = 0.0;

    state.Cpugr = 0.0;
    state.Cnugr = 0.0;

    state.time = 0.0;
end


function [available, axialForce] = readDamperForce( ...
    ops, elementTag, caseType, direction)
%READDAMPERFORCE Read the axial damper force from the current Element state.
%
% Native twoNodeLink:
%   "basicForce" returns the scalar uniaxial material force directly.
%
% callbackSubstructure:
%   "interfaceForce" returns the active interface vector in interfacePairs
%   order, here [F1x; F1y; F4x; F4y]. The node-4 translational components
%   are projected onto the damper axis.
%
% The new response API reads data already stored in the C++ Element and does
% not invoke the MATLAB callback.

    available = false;
    axialForce = 0.0;

    if caseType == "complete"
        try
            basicForce = ops.eleResponse(elementTag, "basicForce");
            basicForce = basicForce(:);

            if ~isempty(basicForce)
                axialForce = basicForce(1);
                available = true;
                return;
            end
        catch
        end
    end

    if caseType == "substructure"
        try
            interfaceForce = ops.eleResponse( ...
                elementTag, ...
                "interfaceForce");

            interfaceForce = interfaceForce(:);

            if numel(interfaceForce) == 4
                node4Force = interfaceForce(3:4);
                axialForce = direction.' * node4Force;
                available = true;
                return;
            end
        catch
        end
    end

    % General fallback: read the full OpenSees element resisting-force vector.
    try
        elementForce = ops.eleResponse(elementTag, "force");
        elementForce = elementForce(:);

        if numel(elementForce) >= 6
            % Full two-node, 2D, three-DOF-per-node ordering:
            % [F1x; F1y; M1z; F4x; F4y; M4z]
            node4Force = elementForce(4:5);

        elseif numel(elementForce) == 4
            % Active callbackSubstructure ordering:
            % [F1x; F1y; F4x; F4y]
            node4Force = elementForce(3:4);

        else
            return;
        end

        axialForce = direction.' * node4Force;
        available = true;

    catch
    end
end

function metrics = calculateVerificationMetrics( ...
    complete, substructure, responseError, g)
%CALCULATEVERIFICATIONMETRICS Calculate response agreement indicators.

    metrics.PeakDispComplete_mm = max(abs(complete.roofDisp));
    metrics.PeakDispSubstructure_mm = max(abs(substructure.roofDisp));

    metrics.DispRMSE_mm = ...
        sqrt(mean(responseError.displacement.^2));

    metrics.DispNRMSE_percent = ...
        100.0 * metrics.DispRMSE_mm / ...
        max(metrics.PeakDispComplete_mm, eps);

    metrics.DispMaxError_mm = ...
        max(abs(responseError.displacement));

    metrics.PeakVelocityComplete_mm_s = max(abs(complete.roofVel));
    metrics.PeakVelocitySubstructure_mm_s = max(abs(substructure.roofVel));

    metrics.VelocityRMSE_mm_s = ...
        sqrt(mean(responseError.velocity.^2));

    metrics.VelocityNRMSE_percent = ...
        100.0 * metrics.VelocityRMSE_mm_s / ...
        max(metrics.PeakVelocityComplete_mm_s, eps);

    metrics.PeakAccelComplete_g = ...
        max(abs(complete.roofAccel)) / g;

    metrics.PeakAccelSubstructure_g = ...
        max(abs(substructure.roofAccel)) / g;

    metrics.AccelRMSE_g = ...
        sqrt(mean((responseError.acceleration/g).^2));

    metrics.AccelNRMSE_percent = ...
        100.0 * metrics.AccelRMSE_g / ...
        max(metrics.PeakAccelComplete_g, eps);

    metrics.PeakForceComplete_kN = ...
        max(abs(complete.damperForce));

    metrics.PeakForceSubstructure_kN = ...
        max(abs(substructure.damperForce));

    metrics.ForceRMSE_kN = ...
        sqrt(mean(responseError.damperForce.^2));

    metrics.ForceNRMSE_percent = ...
        100.0 * metrics.ForceRMSE_kN / ...
        max(metrics.PeakForceComplete_kN, eps);

    metrics.ForceMaxError_kN = ...
        max(abs(responseError.damperForce));

    metrics.DispCorrelation = correlationCoefficient( ...
        complete.roofDisp, ...
        substructure.roofDisp);

    metrics.ForceCorrelation = correlationCoefficient( ...
        complete.damperForce, ...
        substructure.damperForce);
end


function r = correlationCoefficient(x, y)
%CORRELATIONCOEFFICIENT Pearson correlation without additional toolboxes.

    x = x(:) - mean(x);
    y = y(:) - mean(y);

    denominator = sqrt(sum(x.^2) * sum(y.^2));

    if denominator <= eps
        r = NaN;
    else
        r = sum(x.*y) / denominator;
    end
end


function plotComparison(x1, y1, x2, y2)
%PLOTCOMPARISON Plot the two models with consistent line formatting.

    plot( ...
        x1, y1, ...
        "-", ...
        "Color", [0.0000, 0.4470, 0.7410], ...
        "LineWidth", 1.30);

    hold on;

    plot( ...
        x2, y2, ...
        "--", ...
        "Color", [0.8500, 0.3250, 0.0980], ...
        "LineWidth", 1.20);
end


function applyPublicationAxes(ax)
%APPLYPUBLICATIONAXES Apply consistent journal-style formatting.

    if nargin < 1 || isempty(ax)
        ax = gca;
    end

    box(ax, "on");
    grid(ax, "on");

    ax.GridLineStyle = ":";
    ax.GridAlpha = 0.18;
    ax.MinorGridAlpha = 0.10;

    ax.XMinorTick = "on";
    ax.YMinorTick = "on";

    ax.TickDir = "in";
    ax.TickLength = [0.015, 0.015];

    ax.LineWidth = 0.8;
    ax.FontSize = 11;

    % Important for LaTeX-rendered tick labels
    ax.TickLabelInterpreter = "latex";

    % Important for existing axis labels and title
    ax.XLabel.Interpreter = "latex";
    ax.YLabel.Interpreter = "latex";
    ax.ZLabel.Interpreter = "latex";
    ax.Title.Interpreter  = "latex";
end


function exportPublicationFigure(figureHandle, outputFolder, fileName)
%EXPORTPUBLICATIONFIGURE Export vector PDF and 600-dpi PNG.

    exportgraphics( ...
        figureHandle, ...
        fullfile(outputFolder, fileName + ".pdf"), ...
        "ContentType", "vector");
    % 
    % exportgraphics( ...
    %     figureHandle, ...
    %     fullfile(outputFolder, fileName + ".png"), ...
    %     "Resolution", 600);
end


function response = truncateResponse(response, numberOfPoints)
%TRUNCATERESPONSE Truncate all vector response histories consistently.

    fields = fieldnames(response);

    for i = 1:numel(fields)
        value = response.(fields{i});

        if isvector(value) && ...
                numel(value) > 1 && ...
                numel(value) >= numberOfPoints

            response.(fields{i}) = value(1:numberOfPoints);
        end
    end
end


function filePath = locateGroundMotionFile(fileNames, exampleFolder)
%LOCATEGROUNDMOTIONFILE Find the record shipped with this example.

    for iFile = 1:numel(fileNames)
        candidate = fullfile(exampleFolder, fileNames(iFile));
        if isfile(candidate)
            filePath = string(candidate);
            return;
        end
    end

    error( ...
        "The TakY.th earthquake record was not found.");
end


function [response, trialState, status] = ...
    viscousDamperCppCallback(action, trial, committedState)
%VISCOUSDAMPERCPPCALLBACK Two-node numerical viscous-damper substructure.
%
% The callback is invoked by callbackSubstructure using an explicit lifecycle:
%
%   "init"          Initialize the response and initial matrices.
%   "trial"         Evaluate a trial response from committedState.
%   "commit"        Accept the trialState returned by the last trial call.
%   "revert"        Optional notification before C++ restores committed data.
%   "revertToStart" Optional notification before C++ restores initial data.
%   "shutdown"      Optional cleanup notification.
%
% Only "init" and "trial" evaluate the constitutive model. This is important:
% evaluating the material again during "commit" would advance the damper state
% twice within the same OpenSees time step.
%
% Interface ordering:
%
%   trial.disp = [u1x; u1y; u4x; u4y]
%   trial.vel  = [v1x; v1y; v4x; v4y]
%
% Returned force ordering:
%
%   response.force = [F1x; F1y; F4x; F4y]
%
% The damper force already depends nonlinearly on velocity. Therefore it is
% returned as response.force, while response.damping is zero. Returning an
% additional damping matrix for the same force would double count damping.

    action = lower(string(action));
    status = int32(0);
    trialState = committedState;

    numberOfInterfaceDofs = trial.activeDofCount;

    % Safe default response for lifecycle actions that do not evaluate the
    % constitutive model. The C++ element ignores force/tangent for commit,
    % revert, revertToStart, and shutdown, but returning a complete response
    % keeps the callback easy to inspect and reuse.
    response.force = zeros(numberOfInterfaceDofs, 1);
    response.tangent = zeros(numberOfInterfaceDofs);
    response.mass = zeros(numberOfInterfaceDofs);
    response.damping = zeros(numberOfInterfaceDofs);

    switch action

        case {"init", "trial"}
            direction = committedState.direction(:);

            displacement = trial.disp(:);
            velocity = trial.vel(:);

            if numel(displacement) ~= 4 || numel(velocity) ~= 4
                error( ...
                    "The two-node damper interface requires four active DOFs.");
            end

            % Relative translational response between the two physical ends.
            relativeDisplacement = ...
                displacement(3:4) - displacement(1:2);

            relativeVelocity = ...
                velocity(3:4) - velocity(1:2);

            % Project the global relative motion onto the damper axis.
            axialDeformation = ...
                direction.' * relativeDisplacement;

            axialVelocity = ...
                direction.' * relativeVelocity;

            if action == "init" || trial.dt <= 0.0
                % At initialization no constitutive time integration is
                % performed. The response starts from committedState.
                axialForce = committedState.Cstress;
                updatedVelocity = committedState.CVel;
                positiveGapReference = committedState.Cpugr;
                negativeGapReference = committedState.Cnugr;
            else
                % Every OpenSees trial starts from committedState. This makes
                % repeated Newton iterations safe because rejected trial
                % states are never reused.
                [ ...
                    axialForce, ...
                    updatedVelocity, ...
                    positiveGapReference, ...
                    negativeGapReference ...
                ] = cppSetTrialStrain( ...
                    axialDeformation, ...
                    axialVelocity, ...
                    trial.dt, ...
                    committedState);
            end

            % Convert the scalar axial force into balanced global end forces.
            node4Force = direction * axialForce;
            node1Force = -node4Force;

            response.force = [
                node1Force
                node4Force
            ];

            % The reference OpenSees ViscousDamper implementation used in this
            % verification returns a zero tangent. The registered K0 is also
            % zero, so the element uses force-based iteration for this device.
            response.tangent = zeros(4, 4);

            % These matrices represent separately assembled M*a and C*v terms.
            % They are zero because the nonlinear velocity-dependent damper
            % force is already included in response.force.
            response.mass = zeros(4, 4);
            response.damping = zeros(4, 4);

            if action == "init"
                response.initialStiffness = zeros(4, 4);
                response.initialMass = zeros(4, 4);
                response.initialDamping = zeros(4, 4);
            end

            % Return a trial state. C++ commits it only after OpenSees accepts
            % the global step.
            trialState.Cstrain = axialDeformation;
            trialState.Cstress = axialForce;
            trialState.CVel = updatedVelocity;
            trialState.Cpugr = positiveGapReference;
            trialState.Cnugr = negativeGapReference;
            trialState.time = trial.time;

        case "commit"
            % committedState is the accepted trialState supplied by C++.
            % No constitutive integration is repeated here.
            trialState = committedState;

        case "revert"
            % C++ restores its committed force, matrices, and MATLAB state.
            % This branch is only an optional notification hook.
            trialState = committedState;

        case "reverttostart"
            % C++ restores the original initialState after this callback.
            trialState = committedState;

        case "shutdown"
            % No external resources are used by this numerical model.
            trialState = committedState;

        otherwise
            error("Unsupported callbackSubstructure action: %s", action);
    end
end

function [stress, velocity, positiveGapReference, negativeGapReference] = ...
    cppSetTrialStrain(strain, strainRate, dt, state)
%CPPSETTRIALSTRAIN Translate ViscousDamper::setTrialStrain for NM = 1.

    if state.NM ~= 1.0
        error( ...
            "This simplified notebook currently supports NM = 1 only.");
    end

    if strainRate == 0.0
        velocity = 0.0;
        acceleration = 0.0;
    else
        velocity = strainRate;
        acceleration = (velocity - state.CVel) / dt;
    end

    minimumFraction = 0.5^state.MaxHalf;

    fraction = 1.0;
    accumulatedFraction = 0.0;

    force0 = state.Cstress;
    velocity0 = state.CVel;

    while accumulatedFraction < 1.0 - 10.0*eps

        fraction = min( ...
            fraction, ...
            1.0 - accumulatedFraction);

        internalDt = fraction * dt;
        velocity1 = velocity0 + acceleration * internalDt;

        [forceTrial, relativeError, absoluteError] = ...
            dormandPrince54( ...
            velocity0, ...
            velocity1, ...
            force0, ...
            internalDt, ...
            state);

        accepted = ...
            relativeError <= state.RelTol || ...
            fraction <= minimumFraction || ...
            abs(absoluteError) <= state.AbsTol;

        if accepted
            velocity0 = velocity1;
            force0 = forceTrial;

            accumulatedFraction = ...
                accumulatedFraction + fraction;
        else
            fraction = max(0.5*fraction, minimumFraction);
        end
    end

    stress = force0;

    positiveGapReference = state.Cpugr;
    negativeGapReference = state.Cnugr;

    if state.LGap > 0.0

        strainIncrement = strain - state.Cstrain;

        if stress > 0.0 && state.Cstress < 0.0
            positiveGapReference = ...
                state.Cstrain + ...
                strainIncrement * abs(stress) / ...
                abs(stress - state.Cstress);

            negativeGapReference = 0.0;

            if abs(strain - positiveGapReference) < state.LGap
                stress = 0.0;
            end
        end

        if stress < 0.0 && state.Cstress > 0.0
            negativeGapReference = ...
                state.Cstrain + ...
                strainIncrement * abs(stress) / ...
                abs(stress - state.Cstress);

            positiveGapReference = 0.0;

            if abs(strain - negativeGapReference) < state.LGap
                stress = 0.0;
            end
        end

        if abs(positiveGapReference) > 0.0 && state.Cstress == 0.0
            if strain > positiveGapReference && ...
                    strain - positiveGapReference < state.LGap
                stress = 0.0;
            end
        end

        if abs(negativeGapReference) > 0.0 && state.Cstress == 0.0
            if strain < negativeGapReference && ...
                    strain - negativeGapReference > -state.LGap
                stress = 0.0;
            end
        end
    end
end


function [yTrial, relativeError, errorEstimate] = ...
    dormandPrince54(v0, v1, y0, h, state)
%DORMANDPRINCE54 Translate ViscousDamper::DormandPrince.

    k1 = damperOde(v0, y0, state) * h;

    k2 = damperOde( ...
        v0 + (v1-v0)*(1/5), ...
        y0 + (1/5)*k1, ...
        state) * h;

    k3 = damperOde( ...
        v0 + (v1-v0)*(3/10), ...
        y0 + (3/40)*k1 + (9/40)*k2, ...
        state) * h;

    k4 = damperOde( ...
        v0 + (v1-v0)*(4/5), ...
        y0 + (44/45)*k1 - (56/15)*k2 + (32/9)*k3, ...
        state) * h;

    k5 = damperOde( ...
        v0 + (v1-v0)*(8/9), ...
        y0 + (19372/6561)*k1 - ...
        (25360/2187)*k2 + ...
        (64448/6561)*k3 - ...
        (212/729)*k4, ...
        state) * h;

    k6 = damperOde( ...
        v1, ...
        y0 + (9017/3168)*k1 - ...
        (355/33)*k2 + ...
        (46732/5247)*k3 + ...
        (49/176)*k4 - ...
        (5103/18656)*k5, ...
        state) * h;

    yTrial = ...
        y0 + ...
        (35/384)*k1 + ...
        (500/1113)*k3 + ...
        (125/192)*k4 - ...
        (2187/6784)*k5 + ...
        (11/84)*k6;

    k7 = damperOde(v1, yTrial, state) * h;

    errorEstimate = ...
        (71/57600)*k1 - ...
        (71/16695)*k3 + ...
        (71/1920)*k4 - ...
        (17253/339200)*k5 + ...
        (22/525)*k6 - ...
        (1/40)*k7;

    relativeError = ...
        safeRelativeError(errorEstimate, yTrial);
end


function derivative = damperOde(velocity, force, state)
%DAMPERODE ViscousDamper differential equation.

    derivative = ...
        (velocity - ...
        signCpp(force) * ...
        (abs(force)/state.C)^(1/state.Alpha)) * state.K;
end


function value = signCpp(x)
%SIGNCPP Reproduce the C++ behavior sgn(0) = +1.

    if x < 0.0
        value = -1.0;
    else
        value = 1.0;
    end
end


function relativeError = safeRelativeError(errorEstimate, responseValue)
%SAFERELATIVEERROR Avoid NaN for a zero response and zero error.

    if responseValue == 0.0
        if errorEstimate == 0.0
            relativeError = 0.0;
        else
            relativeError = inf;
        end
    else
        relativeError = abs(errorEstimate / responseValue);
    end
end


function forceHistory = replayViscousDamperCpp( ...
    deformationHistory, velocityHistory, timeHistory, damper)
%REPLAYVISCOUSDAMPERCPP Reconstruct force if eleResponse is unavailable.

    state = createInitialDamperState(damper, [1.0; 0.0]);

    forceHistory = zeros(size(deformationHistory));

    for i = 2:numel(deformationHistory)

        dt = timeHistory(i) - timeHistory(i-1);

        if dt <= 0.0
            forceHistory(i) = state.Cstress;
            continue;
        end

        [ ...
            currentStress, ...
            currentVelocity, ...
            positiveGapReference, ...
            negativeGapReference ...
        ] = cppSetTrialStrain( ...
            deformationHistory(i), ...
            velocityHistory(i), ...
            dt, ...
            state);

        state.Cstrain = deformationHistory(i);
        state.Cstress = currentStress;
        state.CVel = currentVelocity;

        state.Cpugr = positiveGapReference;
        state.Cnugr = negativeGapReference;

        forceHistory(i) = currentStress;
    end
end

